const puml = `@startuml
title <size:24>System Context View: Library</size>

set separator none
left to right direction

<style>
  root {
    BackgroundColor: #ffffff
    FontColor: #444444
  }
</style>

!include <C4/C4>
!include <C4/C4_Context>

Person(Patron, "Patron", $descr="Borrows books at the library.", $tags="", $link="")
System(Library, "Library", $descr="Manages books and loans.", $tags="", $link="")

Rel(Patron, Library, "Browses the catalogue through", $techn="HTTPS", $tags="", $link="")

SHOW_LEGEND(true)
hide stereotypes
@enduml
`;
const res = await fetch("https://www.plantuml.com/plantuml/png/", {
  method: "POST",
  headers: { "Content-Type": "text/plain" },
  body: puml,
});
const buf = Buffer.from(await res.arrayBuffer());
const head = buf.slice(0, 8).toString("hex");
return { status: res.status, contentType: res.headers.get("content-type"), size: buf.length, head, b64: buf.toString("base64") };

